const portalSession=window.CEI_SESSION||{};
async function portalCall(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir.');return d}
window.portalRender=()=>{
 const teacher=portalSession.role==='teacher',a=document.getElementById('app');
 if(state.view==='solicitacoes'&&!teacher){document.getElementById('title').textContent='Solicitações de empréstimo';document.getElementById('subtitle').textContent='Aprovação e acompanhamento';portalRequests(a,true);return true}
 if(state.view==='acessos'&&!teacher){document.getElementById('title').textContent='Acessos e publicações';document.getElementById('subtitle').textContent='Gerencie a equipe e os materiais da área pública';portalAdmin(a);return true}
 if(!teacher)return false;
 document.getElementById('title').textContent=state.view==='biblioteca'?'Biblioteca':'Área dos docentes';document.getElementById('subtitle').textContent='Seus documentos, solicitações e empréstimos';
 if(state.view==='biblioteca'){portalLibrary(a);return true}
 if(state.view==='documentos'){
 a.innerHTML=`<div class="panel"><button onclick="openDocGen('praticaAlimentar')">+ Registro de prática alimentar</button><button onclick="openChildReport()">+ Relatório avaliativo</button></div><div id="teacherReports"></div><div class="panel"><h3>Meus registros de alimentação</h3><div id="categoryGenerated"></div></div>`;
 renderChildReports(document.getElementById('teacherReports'));renderCategoryGenerated(['praticaAlimentar']);return true;
 }
 a.innerHTML=`<div class="panel"><h2>Bem-vindo(a) à área dos docentes</h2><p>Consulte o acervo, solicite livros e prepare seus registros pedagógicos.</p><div class="actions"><button onclick="portalNavigate('biblioteca')">Acervo e meus empréstimos</button><button onclick="portalNavigate('documentos')">Meus documentos</button></div></div>`;return true;
};
window.portalNavigate=view=>{state.view=view;render()};
window.addEventListener('DOMContentLoaded',()=>{
 const nav=document.getElementById('nav');
 if(portalSession.role==='teacher')nav.innerHTML='<button onclick="portalNavigate(\'dashboard\')">⌂ Início</button><button onclick="portalNavigate(\'biblioteca\')">📚 Biblioteca</button><button onclick="portalNavigate(\'documentos\')">▣ Documentos</button>';
 else{const b=document.createElement('button');b.textContent='⚙ Acessos e publicações';b.onclick=()=>portalNavigate('acessos');nav.append(b);const req=document.createElement('button');req.textContent='Solicitações de empréstimo';req.onclick=()=>portalNavigate('solicitacoes');nav.append(req)}
 const footer=document.createElement('div');footer.style.cssText='padding:16px;color:inherit;font-size:12px;overflow-wrap:anywhere';footer.innerHTML=`<p>${esc(portalSession.email)}</p><p>${portalSession.role==='admin'?'Administrativo':'Docente'}</p><button onclick="retryShared()">Reconectar dados</button><a href="/" style="color:inherit">Área pública</a> · <a href="/signout-with-chatgpt?return_to=%2F" target="_top" style="color:inherit">Sair</a>`;nav.after(footer);
});
function portalLibrary(a){a.innerHTML=`<div class="panel"><h2>Acervo bibliográfico</h2><p>A retirada e a devolução são registradas pela administração. Você pode solicitar um livro, inclusive quando estiver indisponível, e aguardar aprovação.</p><input id="teacherBookSearch" aria-label="Buscar livro" placeholder="Digite título, autor ou código…" oninput="portalBooks()"><div id="teacherBooks"></div></div><div class="panel"><h2>Meus empréstimos</h2>${state.loans.length?`<table class="table"><thead><tr><th>Livro</th><th>Devolução prevista</th><th>Situação</th></tr></thead><tbody>${state.loans.map(l=>`<tr><td>${esc(l.bookTitle)}</td><td>${esc(l.due)}</td><td>${l.returned?'Devolvido':'Em empréstimo'}</td></tr>`).join('')}</tbody></table>`:'<p>Nenhum empréstimo vinculado à sua conta.</p>'}</div><div id="teacherRequests"></div>`;portalBooks();portalRequests(document.getElementById('teacherRequests'),false)}
window.portalBooks=()=>{const q=(document.getElementById('teacherBookSearch')?.value||'').toLocaleLowerCase('pt-BR');const books=state.books.filter(b=>[b.title,b.author,b.cutter,b.isbn].join(' ').toLocaleLowerCase('pt-BR').includes(q));document.getElementById('teacherBooks').innerHTML=`<p>${books.length} livro(s) encontrado(s)</p><table class="table"><thead><tr><th>Livro / código</th><th>Disponibilidade</th><th>Ação</th></tr></thead><tbody>${books.slice(0,100).map(b=>{const available=Math.max(0,(Number(b.quantity)||1)-(b.unavailable||0));return `<tr><td><b>${esc(b.title)}</b><br>${esc(b.cutter||b.isbn||'')} · ${esc(b.author||'')}</td><td style="color:${available?'#166534':'#b91c1c'}">${available?available+' disponível(is)':'Indisponível'}</td><td><button data-book="${esc(b.id)}">Solicitar empréstimo</button></td></tr>`}).join('')}</tbody></table>${books.length>100?'<p>Refine a busca para encontrar outros títulos.</p>':''}`;document.querySelectorAll('[data-book]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await portalCall('portal/requests',{bookId:b.dataset.book});notify('Solicitação enviada à administração.');portalRequests(document.getElementById('teacherRequests'),false)}catch(e){alert(e.message)}finally{b.disabled=false}})};
async function portalRequests(root,admin){try{const requests=await portalCall('portal/requests');root.innerHTML=`<div class="panel"><h2>${admin?'Solicitações de empréstimo':'Minhas solicitações'}</h2><p>${admin?'A aprovação registra o empréstimo e verifica a disponibilidade do exemplar.':''}</p>${requests.length?`<table class="table"><thead><tr><th>Livro</th>${admin?'<th>Docente</th>':''}<th>Situação</th><th>Data / ações</th></tr></thead><tbody>${requests.slice().reverse().map(r=>`<tr><td>${esc(r.title)}</td>${admin?`<td>${esc(r.name)}<br>${esc(r.email)}</td>`:''}<td>${({pending:'Aguardando aprovação',approved:'Aprovado',rejected:'Não aprovado'})[r.status]}</td><td>${admin&&r.status==='pending'?`<input type="date" aria-label="Devolução prevista" id="due-${esc(r.id)}"><button data-decision="approved" data-request="${esc(r.id)}">Aprovar</button><button data-decision="rejected" data-request="${esc(r.id)}">Recusar</button>`:esc(r.createdAt.slice(0,10))}</td></tr>`).join('')}</tbody></table>`:'<p>Nenhuma solicitação.</p>'}</div>`;root.querySelectorAll('[data-decision]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await sharedQueue;await portalCall('portal/decision',{id:b.dataset.request,status:b.dataset.decision,due:document.getElementById('due-'+b.dataset.request).value});await initializeShared(false);portalRequests(root,admin)}catch(e){alert(e.message);b.disabled=false}})}catch(e){root.textContent=e.message}}
async function portalAdmin(root){try{const [members,pubs,authCfg]=await Promise.all([portalCall('portal/members'),portalCall('portal/publications'),fetch('/api/auth/config',{cache:'no-store'}).then(r=>r.json()).catch(()=>({}))]);const pw=authCfg.provider==='senha';root.innerHTML=`<div class="panel"><h2>Equipe e permissões</h2><p>${pw?'Cadastre o e-mail da pessoa e uma senha inicial. No primeiro acesso, ela cria a própria senha.':'Cadastre o e-mail usado pela pessoa ao entrar com o ChatGPT.'} O perfil Administrativo tem acesso completo; Docente tem acesso somente às funções pedagógicas e aos próprios registros. Sem cadastro, o acesso interno fica bloqueado.</p><form id="memberForm"><label>Nome<input name="name" required></label><label>E-mail da conta<input name="email" type="email" required></label>${pw?'<label>Senha inicial (mín. 8 caracteres; deixe vazio para manter a atual)<input name="password" type="text" minlength="8" autocomplete="off" placeholder="Ex.: Cei@2026-maria"></label>':''}<label>Perfil<select name="role"><option value="teacher">Docente</option><option value="admin">Administrativo</option><option value="pending">Bloqueado</option></select></label><label>Vincular histórico de leitor existente (opcional)<select name="readerId"><option value="">Sem vínculo</option>${state.readers.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')}</select></label><button class="primary">Salvar acesso</button></form><p>A conta proprietária do site mantém o acesso administrativo de recuperação.</p><p>Para alterar ou bloquear um acesso, informe novamente o mesmo e-mail.</p><table class="table"><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th>${pw?'<th>Senha</th>':''}</tr></thead><tbody>${members.map(m=>`<tr><td>${esc(m.name)}</td><td>${esc(m.email)}</td><td>${({admin:'Administrativo',teacher:'Docente',pending:'Bloqueado'})[m.role]}</td>${pw?`<td>${m.hasPassword?(m.mustChange?'<span class="muted">Aguardando 1º acesso</span>':'✓ Definida'):'<span style="color:#b42318">Sem senha</span>'} <button type="button" data-pw="${esc(m.email)}">${m.hasPassword?'Redefinir':'Definir'}</button></td>`:''}</tr>`).join('')}</tbody></table></div><div class="panel"><h2>Documentos da área pública</h2><p>Publique apenas materiais destinados à comunidade. Documentos internos permanecem restritos até sua seleção aqui.</p><input id="publicationSearch" placeholder="Pesquisar por título…" aria-label="Pesquisar documentos"><div id="publicationList"></div></div>`;
 document.getElementById('memberForm').closest('.panel').querySelectorAll('[data-pw]').forEach(b=>b.onclick=async()=>{const pass=prompt('Nova senha para '+b.dataset.pw+' (mín. 8 caracteres). A pessoa deverá trocá-la no próximo acesso:');if(!pass)return;try{await portalCall('portal/password',{email:b.dataset.pw,password:pass});notify('Senha definida. Informe-a à pessoa por um canal seguro.');portalAdmin(root)}catch(err){alert(err.message)}});document.getElementById('memberForm').onsubmit=async e=>{e.preventDefault();const input=Object.fromEntries(new FormData(e.target));try{await sharedQueue;await portalCall('portal/members',input);notify('Acesso atualizado.');portalAdmin(root)}catch(err){alert(err.message)}};
 const list=()=>{const q=document.getElementById('publicationSearch').value.toLowerCase();document.getElementById('publicationList').innerHTML=pubs.records.filter(r=>r.file&&r.title.toLowerCase().includes(q)).map(r=>`<p><label><input type="checkbox" data-publish="${esc(r.id)}" ${pubs.ids.includes(r.id)?'checked':''} style="width:auto"> ${esc(r.title)}</label></p>`).join('')||'<p>Nenhum arquivo encontrado. Envie documentos pelo Arquivo central e publique-os em Sistema → Página pública.</p>';document.querySelectorAll('[data-publish]').forEach(b=>b.onchange=async()=>{try{await portalCall('portal/publications',{id:b.dataset.publish,published:b.checked});pubs.ids=b.checked?[...pubs.ids,b.dataset.publish]:pubs.ids.filter(id=>id!==b.dataset.publish);notify('Publicação atualizada.')}catch(e){b.checked=!b.checked;alert(e.message)}})};document.getElementById('publicationSearch').oninput=list;list();
 }catch(e){root.textContent=e.message}}

window.addEventListener('beforeunload',event=>{if(localStorage.getItem('cei-shared-dirty')==='1'){event.preventDefault();event.returnValue='Há alterações ainda não enviadas ao servidor.'}});
